"""The in-task review verifier. Generated by eval-harvest emit; do not edit by hand.

Produces the reward object's *shape* (ADR-5) at reduced sophistication: deterministic
path+line narrowing, then a **greedy** one-to-one match, then an LLM judge for semantic equivalence
on the narrowed candidates, then a reward object with coverage and precision kept separate and
per-severity counts. It is stdlib-only and pinned: the judge model comes from ``judge.toml`` and the
reward-kit override variables are scrubbed by ``test.sh`` before this runs.

Two honesty properties are deliberate:

- **Unmatched agent findings are counted *uncredited*, never *false*.** The human review this oracle
  was mined from is an incomplete reference (a defect the reviewers missed is not a false positive),
  so a finding the agent raised that no oracle finding matches lowers precision but is never scored
  as a wrong answer. Teaching the eval that a human-missed finding is a false positive is exactly the
  failure ADR-5 avoids.
- **Greedy match understates, which is the safe direction.** In rare multi-claim cases a greedy
  one-to-one match credits fewer findings than a maximum-cardinality assignment would — it
  under-credits the agent, never over-credits it. A fuller maximum-cardinality matcher can replace
  this without changing the reward shape.

This file is *data* the CLI writes into each task; the CLI never imports or runs it. It runs under
Harbor at eval time, where the judge reaches a model; in CI it is exercised with a recorded judge.
"""

from __future__ import annotations

import json
import os
import tomllib
from collections.abc import Callable
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any  # JSON parsed from disk is genuinely arbitrary until narrowed to the shapes below.

#: The reward object's keys, the set the dataset ``metric.py`` averages. Every key is meaningful
#: under a mean: coverage/precision are ratios in [0, 1] and the counts are per-trial tallies.
REWARD_KEYS: tuple[str, ...] = (
    "coverage_required",
    "coverage_all",
    "precision_strict",
    "precision_adjudicated",
    "credited_required",
    "credited_all",
    "uncredited",
    "oracle_high",
    "oracle_medium",
    "oracle_low",
    "credited_high",
    "credited_medium",
    "credited_low",
)

#: Only high-severity findings block a merge (FR-14); "required" coverage is measured over them.
_BLOCKING_SEVERITY = "high"
_SEVERITIES = ("high", "medium", "low")

#: The only scheme :class:`LiveJudge` will open. The endpoint is configurable; its scheme is not — see
#: :meth:`LiveJudge.require_transport_security`.
REQUIRED_ENDPOINT_SCHEME = "https://"

_ORACLE_PATH = Path("/tests/oracle.json")
_JUDGE_CONFIG_PATH = Path("/tests/judge.toml")
_REWARD_PATH = Path("/logs/verifier/reward.json")
#: Where the evaluated agent wrote its findings; overridable so the oracle solution and tests can
#: point it at a fixture.
#:
#: The default is under the artifacts convention dir (``/logs/artifacts``), not ``/logs/agent``,
#: because in ``separate`` verifier mode the verifier runs in its own environment and Harbor transfers
#: only the agent environment's artifacts dir into it — never ``/logs/agent`` (trial.py:706-712,
#: artifact_handler.upload_artifacts, models/task/artifacts.with_convention_entry). A submission written
#: under ``/logs/agent`` never reaches this scorer, so every graded trial reads an empty submission and
#: scores ``coverage_all = 0``. The writer (``solve.sh``, ``instruction.md``) must agree with this
#: path; ``test_agent_findings_path_reaches_the_separate_verifier`` pins that.
_AGENT_FINDINGS_ENV = "EVAL_HARVEST_AGENT_FINDINGS"
_DEFAULT_AGENT_FINDINGS = Path("/logs/artifacts/findings.json")


@dataclass(frozen=True, slots=True)
class Location:
    """One file+line span a reference finding points at, taken from the review comment it groups."""

    path: str
    line_start: int
    line_end: int

    def contains(self, path: str, line: int) -> bool:
        """True when ``path``/``line`` falls inside this span (the deterministic narrowing test)."""
        return path == self.path and self.line_start <= line <= self.line_end


@dataclass(frozen=True, slots=True)
class OracleFinding:
    """One reference finding: what a reviewer flagged, its severity, and where it lives."""

    id: int
    statement: str
    severity: str
    reference_only: bool
    locations: tuple[Location, ...]

    @property
    def required(self) -> bool:
        """A required (blocking) finding is a high-severity one the agent is expected to catch.

        Named ``required`` rather than ``is_required``: as a property it is read without parentheses,
        and an ``is_``-prefixed attribute read bare is indistinguishable from a method call someone
        forgot to finish — the mistake linters flag on sight.
        """
        return self.severity == _BLOCKING_SEVERITY


@dataclass(frozen=True, slots=True)
class AgentFinding:
    """One finding the evaluated agent submitted, with the index that keys a judge decision."""

    index: int
    path: str
    line: int
    statement: str
    severity: str


#: A judge decides semantic equivalence for a candidate pair that already agrees on file+line.
Judge = Callable[[OracleFinding, AgentFinding], bool]


def _accept_on_location(_oracle_finding: OracleFinding, _agent_finding: AgentFinding) -> bool:
    """The strict tier's predicate: a location overlap is enough, no semantic judgement.

    Passed where :meth:`Score._greedy_match` takes a judge, so the strict match reuses the identical
    greedy one-to-one logic while consulting no model — the difference between the two match sizes is
    precisely the credit the real judge withholds.
    """
    return True


@dataclass(frozen=True, slots=True)
class RecordedJudge:
    """Replays pinned equivalence decisions, keyed by ``(oracle_id, agent_index)`` (S-19, ADR-5).

    Harbor runs a live model at eval time; CI runs this instead so the reward math is tested without
    a model in the tree — a recorded judge that replays pinned decisions. A pair
    with no recorded decision is treated as *not equivalent*, so a missing record never silently
    credits a finding.
    """

    decisions: dict[tuple[int, int], bool] = field(default_factory=dict)

    def __call__(self, oracle_finding: OracleFinding, agent_finding: AgentFinding) -> bool:
        return self.decisions.get((oracle_finding.id, agent_finding.index), False)

    @classmethod
    def from_file(cls, path: Path) -> RecordedJudge:
        """Load recorded decisions from a JSON list of ``{oracle_id, agent_index, equivalent}``."""
        raw: Any = json.loads(path.read_text(encoding="utf-8"))
        decisions: dict[tuple[int, int], bool] = {}
        for entry in raw.get("decisions", []):
            decisions[(int(entry["oracle_id"]), int(entry["agent_index"]))] = bool(entry["equivalent"])
        return cls(decisions)


@dataclass(frozen=True, slots=True)
class LiveJudge:
    """Asks the pinned Bedrock model whether two same-location findings describe the same defect.

    Never exercised in CI (no model, and no ``boto3``, in the tree); it is the eval-time path. It runs
    *inside* the verifier MicroVM, which the platform launches under a Bedrock-capable IAM execution role
    (``lambda_microvms`` passes ``execution_role_arn``). ``boto3`` discovers those role credentials the
    way it discovers any container/instance role — there is no API key, and none should exist. The
    model is pinned by ``judge.toml`` and the override variables are scrubbed by ``test.sh``, so the pin
    holds; ``temperature = 0`` is the determinism lever (Bedrock ``Converse`` has no ``seed``).
    """

    model: str
    temperature: float
    seed: int
    region: str
    endpoint: str

    @classmethod
    def from_config(cls, path: Path) -> LiveJudge:
        """Read the pinned judge config from ``judge.toml`` and resolve the Bedrock region from the env."""
        config: Any = tomllib.loads(path.read_text(encoding="utf-8"))
        judge = config.get("judge", {})
        region = os.environ.get("AWS_REGION") or os.environ.get("AWS_DEFAULT_REGION") or ""
        if not region:
            raise ValueError(
                "the judge needs an AWS region to reach Bedrock — set AWS_REGION in the verifier "
                "environment (the MicroVM platform sets it for the execution role)"
            )
        return cls(
            model=str(judge.get("model", "")),
            temperature=float(judge.get("temperature", 0.0)),
            seed=int(judge.get("seed", 0)),
            region=region,
            endpoint=f"https://bedrock-runtime.{region}.amazonaws.com",
        )

    @staticmethod
    def require_transport_security(endpoint: str) -> None:
        """Refuse a judge endpoint whose scheme is not ``https://``.

        The endpoint is derived from the region (``AWS_REGION``) the verifier environment supplies, so a
        crafted region must not be able to downgrade the Bedrock call to a plaintext or ``file://``
        transport whose answer an agent could control. The region stays configurable; the scheme does not.
        """
        if not endpoint.startswith(REQUIRED_ENDPOINT_SCHEME):
            raise ValueError(
                f"the judge endpoint must start with {REQUIRED_ENDPOINT_SCHEME!r}, got {endpoint!r} — "
                f"a non-https transport could source the judge's answer from a place the agent controls"
            )

    def __call__(self, oracle_finding: OracleFinding, agent_finding: AgentFinding) -> bool:
        self.require_transport_security(self.endpoint)
        # Lazy import: this file is data the CLI writes into each task and never imports, and ``boto3``
        # lives in the verifier image, not the dev tree — importing here keeps ``score.py`` loadable
        # and its offline tests runnable without ``boto3`` installed.
        import boto3  # noqa: PLC0415

        prompt = (
            "Two code-review findings refer to the same file and line. Do they describe the same "
            "underlying defect? Answer only 'yes' or 'no'.\n\n"
            f"Reference finding: {oracle_finding.statement}\n"
            f"Agent finding: {agent_finding.statement}\n"
        )
        client = boto3.client("bedrock-runtime", region_name=self.region, endpoint_url=self.endpoint)
        response: Any = client.converse(
            modelId=self.model,
            messages=[{"role": "user", "content": [{"text": prompt}]}],
            inferenceConfig={"temperature": self.temperature, "maxTokens": 5},
        )
        answer = response["output"]["message"]["content"][0]["text"]
        return str(answer).strip().lower().startswith("y")


class Score:
    """Deterministic narrowing, greedy matching, and the reward object. Holds no state."""

    @classmethod
    def compute_reward(cls, oracle: list[OracleFinding], agent: list[AgentFinding], judge: Judge) -> dict[str, float]:
        """The reward object: coverage and precision kept separate, per-severity counts, uncredited.

        Unmatched agent findings are counted ``uncredited`` — they lower precision but are never
        scored as false positives (ADR-5). The two ratio families answer the empty denominator
        differently, on purpose: **coverage** is ``1.0`` over an empty oracle or an empty required
        set (an agent cannot miss a finding that does not exist), while **precision** is ``0.0`` over
        an empty submission (declining to review demonstrates no precision — see
        :meth:`_precision_ratio`).

        **The two precision keys are two measurements, not one printed twice.**
        ``precision_adjudicated`` divides by the judge-gated credited set (the same set that feeds
        coverage and ``credited_*``); ``precision_strict`` divides by the deterministic
        location-overlap set, computed with no judge (:meth:`_location_only_match`). Comparing them
        tells a reader how much of the agent's credit depends on the judge — a robustness check that a
        single shared expression silently skipped.
        """
        matched = cls._greedy_match(oracle, agent, judge)
        credited_oracle = [finding for finding in oracle if finding.id in matched]
        required = [finding for finding in oracle if finding.required]
        credited_required = [finding for finding in credited_oracle if finding.required]
        credited_count = len(credited_oracle)
        uncredited = len(agent) - credited_count
        # The strict tier credits by deterministic path+line overlap alone, with no judge call, so the
        # two precision keys are genuinely different measurements: `precision_adjudicated` is what
        # the judge credits, `precision_strict` is what survives without it. A reader compares them to
        # sanity-check the judge — if the judge is generous or drifts, they diverge. Coverage and every
        # `credited_*` key stay on the adjudicated set (ADR-5, S-19): the judge-gated match is the one
        # that decides what the agent is credited for; only the precision denominator gains a second view.
        strict_credited_count = len(cls._location_only_match(oracle, agent))
        reward: dict[str, float] = {
            "coverage_required": cls._ratio(len(credited_required), len(required)),
            "coverage_all": cls._ratio(credited_count, len(oracle)),
            "precision_strict": cls._precision_ratio(strict_credited_count, len(agent)),
            "precision_adjudicated": cls._precision_ratio(credited_count, len(agent)),
            "credited_required": float(len(credited_required)),
            "credited_all": float(credited_count),
            "uncredited": float(uncredited),
        }
        for severity in _SEVERITIES:
            reward[f"oracle_{severity}"] = float(sum(finding.severity == severity for finding in oracle))
            reward[f"credited_{severity}"] = float(sum(finding.severity == severity for finding in credited_oracle))
        return reward

    @classmethod
    def _greedy_match(cls, oracle: list[OracleFinding], agent: list[AgentFinding], judge: Judge) -> dict[int, int]:
        """Map each *adjudicated* oracle finding id to the agent-finding index it was credited to.

        Greedy and one-to-one: oracle findings are considered in order, and each takes the first
        still-unclaimed agent finding that overlaps its location *and* the judge deems equivalent. This
        is the set coverage and ``credited_*`` are computed from.
        """
        return cls._greedy_match_where(oracle, agent, judge)

    @classmethod
    def _location_only_match(cls, oracle: list[OracleFinding], agent: list[AgentFinding]) -> dict[int, int]:
        """The strict match: greedy one-to-one on location overlap alone, with **no judge**.

        Takes no ``judge`` argument by design — the strict precision tier is judge-free, so this method
        cannot consult one. It credits every oracle finding a location-overlapping agent finding exists
        for, which is a superset of :meth:`_greedy_match`'s judge-gated set; the difference between the
        two counts is exactly what the judge rejected.
        """
        return cls._greedy_match_where(oracle, agent, _accept_on_location)

    @classmethod
    def _greedy_match_where(cls, oracle: list[OracleFinding], agent: list[AgentFinding], accept: Judge) -> dict[int, int]:
        """Greedy one-to-one match crediting the first unclaimed location overlap ``accept`` approves."""
        claimed: set[int] = set()
        matched: dict[int, int] = {}
        for finding in oracle:
            candidate = cls._first_accepted(finding, agent, claimed, accept)
            if candidate is not None:
                matched[finding.id] = candidate.index
                claimed.add(candidate.index)
        return matched

    @staticmethod
    def _first_accepted(
        finding: OracleFinding, agent: list[AgentFinding], claimed: set[int], accept: Judge
    ) -> AgentFinding | None:
        """The first unclaimed agent finding that overlaps ``finding``'s location and ``accept`` approves."""
        for candidate in agent:
            if candidate.index in claimed:
                continue
            if not any(location.contains(candidate.path, candidate.line) for location in finding.locations):
                continue
            if accept(finding, candidate):
                return candidate
        return None

    @staticmethod
    def _ratio(numerator: int, denominator: int) -> float:
        """A **coverage** ratio: ``numerator / denominator``, or ``1.0`` when the denominator is empty.

        For coverage keys only, where an empty denominator means *nothing to miss* — an agent cannot
        fail to cover a finding the oracle does not contain. Precision has the opposite answer and its
        own helper (:meth:`_precision_ratio`); a single shared helper is what let an empty submission
        score perfect precision.
        """
        return numerator / denominator if denominator else 1.0

    @staticmethod
    def _precision_ratio(numerator: int, denominator: int) -> float:
        """A **precision** ratio: ``numerator / denominator``, or ``0.0`` when the submission is empty.

        Precision answers "of what you raised, how much was real". An agent that raised nothing has no
        answer, not a perfect one, so an empty submission scores ``0.0`` — otherwise silence is the
        dominant strategy under Harbor's ``Mean()`` aggregation, and a systematically silent agent
        outranks one that reviews well but imperfectly.
        """
        return numerator / denominator if denominator else 0.0


def load_oracle(path: Path) -> list[OracleFinding]:
    """Parse ``oracle.json`` into typed reference findings."""
    raw: Any = json.loads(path.read_text(encoding="utf-8"))
    return [_oracle_finding(entry) for entry in raw["findings"]]


def _oracle_finding(entry: Any) -> OracleFinding:
    locations = tuple(
        Location(str(loc["path"]), int(loc["line_start"]), int(loc["line_end"])) for loc in entry.get("locations", [])
    )
    return OracleFinding(
        id=int(entry["id"]),
        statement=str(entry.get("statement", "")),
        severity=str(entry.get("severity", "")),
        reference_only=bool(entry.get("reference_only", False)),
        locations=locations,
    )


def load_agent_findings(path: Path) -> list[AgentFinding]:
    """Parse the agent's submitted findings; a missing or malformed file is an empty submission."""
    if not path.is_file():
        return []
    raw: Any = json.loads(path.read_text(encoding="utf-8"))
    return [_agent_finding(index, entry) for index, entry in enumerate(raw)]


def _agent_finding(index: int, entry: Any) -> AgentFinding:
    return AgentFinding(
        index=index,
        path=str(entry.get("path", "")),
        line=int(entry.get("line", 0)),
        statement=str(entry.get("statement", "")),
        severity=str(entry.get("severity", "")),
    )


def select_judge() -> Judge:
    """The recorded judge when a recording is present, otherwise the pinned live judge."""
    recording = os.environ.get("EVAL_HARVEST_JUDGE_RECORDING")
    if recording:
        return RecordedJudge.from_file(Path(recording))
    return LiveJudge.from_config(_JUDGE_CONFIG_PATH)


def main() -> None:
    """Score the agent's submission against the oracle and write ``reward.json`` (Harbor reads it)."""
    oracle = load_oracle(_ORACLE_PATH)
    findings_path = Path(os.environ.get(_AGENT_FINDINGS_ENV, str(_DEFAULT_AGENT_FINDINGS)))
    agent = load_agent_findings(findings_path)
    reward = Score.compute_reward(oracle, agent, select_judge())
    _REWARD_PATH.parent.mkdir(parents=True, exist_ok=True)
    _REWARD_PATH.write_text(json.dumps(reward, sort_keys=True), encoding="utf-8")


if __name__ == "__main__":
    main()
